"use client";
import { Button, Form } from "react-bootstrap";
import Image from "next/image";
import { movie1 } from "@/assets";
import { UseLogin } from "../useLogin";
export default function Login() {
const {formik} = UseLogin();
  return (
  <div className="position-relative min-vh-100 vw-100 d-flex justify-content-center align-items-center">
    <Image
      src={movie1.src}
      alt="background"
      fill
      priority
      unoptimized
      style={{              
        objectFit:"cover",         
        opacity:0.6     
      }}
    />
    <Form 
      onSubmit={formik.handleSubmit} 
      className="p-5 border-0 rounded-4 shadow-lg text-primary fw-bold" 
      style={{ 
        width: "450px", 
        backgroundColor: "rgba(255, 255, 255, 0.85)", 
        backdropFilter: "blur(10px)" 
      }}
    >
      <h3 className="mb-4 text-center text-info display-6 fw-bold">
        Login</h3>
      <Form.Group className="mb-3">
        <Form.Label>Email Address</Form.Label>
        <Form.Control
          name="email"
          type="email"
          onChange={formik.handleChange}
          onBlur={formik.handleBlur}
          value={formik.values.email}
          placeholder="Enter your email"
          isInvalid={!!(formik.touched.email && formik.errors.email)}
        />
        <Form.Control.Feedback type="invalid">{formik.errors.email}</Form.Control.Feedback>
      </Form.Group>
      <Form.Group className="mb-3">
        <Form.Label>Password</Form.Label>
        <Form.Control
          name="password" 
          type="password"
          onChange={formik.handleChange}
          onBlur={formik.handleBlur}
          value={formik.values.password}
          isInvalid={!!(formik.touched.password && formik.errors.password)}
        />
        <Form.Control.Feedback type="invalid">{formik.errors.password}</Form.Control.Feedback>
      </Form.Group>
      <div className="d-grid">
        <Button size="lg" type="submit" variant="info" className="text-white fw-bold">
          Login
        </Button>
      </div>
    </Form>
  </div>
);
}
